// 本叶读取原fact真M并反核唯一Office历史，绝不倒补旧来源的offset。
#include "politics_time2.hpp"
#include <algorithm>
namespace hanmo::resident {
Outcome<WorldMoment> NativePoliticsAuthorityRead::read_organization_authority_now()const{return hanmo::resident::read_organization_authority_now(common_,&clock_);}
Outcome<AuthorityIssueSourceView> NativePoliticsAuthorityRead::read_authority_issue_source(const SourceRef& source)const{const auto* f=state_.facts.find(source.id);const auto* h=common_.state().facts.find(source.id);if(!f||!h||source.domain!="politics"||f->kind!=source.kind||h->kind!=source.kind||h->domain!=source.domain||!f->occurred_at||f->occurred_at->half_day_tick!=f->tick||f->decision_actor_id.empty())return {false,{},common_failure("PoliticalAuthorityOriginalSourceRequired",source.id).error};StableId command;if(f->kind=="political_appointment_offered"||f->kind=="political_appointment_withdrawn")command="political_appoint";else if(f->kind=="political_office_dismissed")command="political_dismiss";else return {false,{},common_failure("PoliticalSourceNotAuthorityIssue",source.id).error};ActorFoundationAt at;at.kind=ActorFoundationAt::Kind::exact_moment;at.exact_moment=*f->occurred_at;return {true,{source,f->decision_actor_id,std::move(command),std::move(at),{}},{}};}
Status validate_politics_time2_authorities(const CommonStore& common,const PoliticsState& politics,const OrganizationState& organizations,const OrganizationCatalog& catalog,const OrganizationRuntime& runtime,const OrganizationAuthorityClock& clock){NativePoliticsAuthorityRead reader(common,politics,clock);for(const auto& row:politics.facts.rows()){const auto& f=row.second;const bool authority=f.kind=="political_appointment_offered"||f.kind=="political_appointment_withdrawn"||f.kind=="political_office_dismissed";if(!authority){if(runtime.authority_bases.find(f.id))return common_failure("PoliticalPersonalDecisionHasAuthorityBasis",f.id);continue;}const auto* j=politics.jurisdictions.find(f.jurisdiction_id);if(!j)return common_failure("PoliticalAuthorityJurisdictionMissing",f.id);auto basis=read_registered_authority_basis(common,runtime.authority_bases,organizations,catalog,catalog.authority_catalog_identity,{{"politics",f.kind,f.id},1},reader);if(!basis.ok)return {false,{},basis.error};if(basis.value->actor_id!=f.decision_actor_id||basis.value->scope.kind!=ScopeRef::Kind::site||basis.value->scope.id!=j->seat_place_id||basis.value->budget_ref||basis.value->organization_id!=f.organization_id)return common_failure("PoliticalAuthorityBasisMismatch",f.id);if(f.kind=="political_appointment_offered"){const auto* a=politics.appointments.find(f.appointment_id);if(!a||basis.value->office_id!=a->issuer_office_id||basis.value->office_epoch!=a->issuer_epoch||basis.value->actor_id!=a->issuer_actor_id)return common_failure("PoliticalOfferAuthorityMismatch",f.id);}}return common_success();}
Outcome<WorldMoment> read_politics_source_moment(const CommonStore& common,const PoliticsState& state,const OrganizationRuntime& runtime,const SourceRef& source,Integer schema,const OrganizationAuthorityClock& clock){
 const auto bad=[&](const StableId& code)->Outcome<WorldMoment>{return {false,{},common_failure(code,source.id).error};};if(schema!=2||source.domain!="politics")return bad("PoliticalTime2SourceRequired");const auto* f=state.facts.find(source.id);const auto* h=common.state().facts.find(source.id);if(!f||!h||f->id!=source.id||h->domain!=source.domain||h->kind!=source.kind||f->kind!=source.kind||!f->occurred_at||f->tick!=f->occurred_at->half_day_tick)return bad("PoliticalTime2SourceMismatch");
 static constexpr const char* kinds[]={"political_appointment_offered","political_appointment_accepted","political_appointment_declined","political_appointment_withdrawn","political_appointment_expired","political_appointment_arrived","political_appointment_invalidated","political_office_dismissed"};bool known=false;for(const auto* kind:kinds)known=known||source.kind==kind;if(!known)return bad("PoliticalTime2SourceKind");auto canonical=encode_world_moment(*f->occurred_at);if(!canonical.ok)return {false,{},canonical.error};auto now=read_organization_authority_now(common,&clock);if(!now.ok)return {false,{},now.error};auto future=compare_world_moments(*f->occurred_at,now.value);if(!future.ok)return {false,{},future.error};if(future.value>0)return bad("PoliticalTime2FutureSource");
 if(f->kind=="political_appointment_arrived"||f->kind=="political_office_dismissed"){const auto* actual=runtime.office_transition_sources.find(f->id);if(!actual||!same_source_ref(actual->source,source)||actual->office_id!=f->office_id||actual->organization_id!=f->organization_id||actual->expected_epoch!=f->office_epoch)return bad("PoliticalTime2OfficeSourceMismatch");auto equal=compare_world_moments(actual->effective_moment,*f->occurred_at);if(!equal.ok)return {false,{},equal.error};if(equal.value)return bad("PoliticalTime2OfficeMomentMismatch");}
 return {true,*f->occurred_at,{}};
}
Status validate_politics_time2(const CommonStore& common,const PoliticsState& state,const OrganizationRuntime& runtime,const OrganizationAuthorityClock& clock){WorldMoment prior{};const auto& order=common.state().facts.order();std::size_t previous=0;bool first=true;for(const auto& row:state.facts.rows()){auto time=read_politics_source_moment(common,state,runtime,{"politics",row.second.kind,row.first},2,clock);if(!time.ok)return {false,{},time.error};auto seq=std::find(order.begin(),order.end(),row.first);if(seq==order.end()||(!first&&static_cast<std::size_t>(seq-order.begin())<=previous))return common_failure("PoliticalTime2FactOrder",row.first);auto compared=compare_world_moments(prior,time.value);if(!compared.ok)return {false,{},compared.error};if(compared.value>0)return common_failure("PoliticalTime2MomentOrder",row.first);for(const auto& id:row.second.cause_fact_ids){auto source=std::find(order.begin(),order.end(),id);if(source==order.end()||source>=seq)return common_failure("PoliticalTime2CauseOrder",id);if(const auto* actual=state.facts.find(id)){if(!actual->occurred_at)return common_failure("PoliticalTime2CauseRequired",id);auto cmp=compare_world_moments(*actual->occurred_at,time.value);if(!cmp.ok)return {false,{},cmp.error};if(cmp.value>0)return common_failure("PoliticalTime2CauseMoment",id);}}previous=static_cast<std::size_t>(seq-order.begin());prior=std::move(time.value);first=false;}
 for(const auto& row:runtime.office_transition_sources.rows())if(row.second.source.domain=="politics"&&(row.second.source.kind=="political_appointment_arrived"||row.second.source.kind=="political_office_dismissed")&&!state.facts.find(row.second.source.id))return common_failure("PoliticalTime2OfficeOriginalMissing",row.first);return common_success();}
}
